Here is the commit message:
wifi: mt76: mt7925: prevent NULL vif dereference in
 mt7925_mac_write_txwi

Check for a NULL `vif` before accessing `ieee80211_vif_is_mld(vif)` to
avoid a potential kernel panic in scenarios where `vif` might not be
initialized.

Fixes: ebb1406813c6 ("wifi: mt76: mt7925: add link handling to txwi")
Signed-off-by: Ming Yen Hsieh <mingyen.hsieh@mediatek.com>
Link: https://patch.msgid.link/20250904030649.655436-3-mingyen.hsieh@mediatek.com
Signed-off-by: Felix Fietkau <nbd@nbd.name>

Here is the root cause:
The function `mt7925_mac_write_txwi` dereferences the `vif` pointer by calling `ieee80211_vif_is_mld(vif)` without first verifying that `vif` is not NULL. In certain TX paths, `vif` can be NULL, leading to a kernel panic.

Here is the patch:

 void
 mt7925_mac_write_txwi(struct mt76_dev *dev, __le32 *txwi,
 		      struct sk_buff *skb, struct mt76_wcid *wcid,
 		      struct ieee80211_key_conf *key, int pid,
 		      enum mt76_txq_id qid, u32 changed)
 {
 	struct ieee80211_tx_info *info = IEEE80211_SKB_CB(skb);
 	struct ieee80211_vif *vif = info->control.vif;
 	u8 p_fmt, q_idx, omac_idx = 0, wmm_idx = 0, band_idx = 0;
 	u32 val, sz_txd = mt76_is_mmio(dev) ? MT_TXD_SIZE : MT_SDIO_TXD_SIZE;
 	bool is_8023 = info->flags & IEEE80211_TX_CTL_HW_80211_ENCAP;
 	struct mt76_vif_link *mvif;
 	bool beacon = !!(changed & (BSS_CHANGED_BEACON |
 				    BSS_CHANGED_BEACON_ENABLED));
 	bool inband_disc = !!(changed & (BSS_CHANGED_UNSOL_BCAST_PROBE_RESP |
 					 BSS_CHANGED_FILS_DISCOVERY));
 	struct mt792x_bss_conf *mconf;

 	mconf = vif ? mt792x_vif_to_link((struct mt792x_vif *)vif->drv_priv,
 					 wcid->link_id) : NULL;
 	mvif = mconf ? (struct mt76_vif_link *)&mconf->mt76 : NULL;

 	if (mvif) {
 		omac_idx = mvif->omac_idx;
 		wmm_idx = mvif->wmm_idx;
 		band_idx = mvif->band_idx;
 	}

 	if (inband_disc) {
 		p_fmt = MT_TX_TYPE_FW;
 		q_idx = MT_LMAC_ALTX0;
 	} else if (beacon) {
 		p_fmt = MT_TX_TYPE_FW;
 		q_idx = MT_LMAC_BCN0;
 	} else if (qid >= MT_TXQ_PSD) {
 		p_fmt = mt76_is_mmio(dev) ? MT_TX_TYPE_CT : MT_TX_TYPE_SF;
 		q_idx = MT_LMAC_ALTX0;
 	} else {
 		p_fmt = mt76_is_mmio(dev) ? MT_TX_TYPE_CT : MT_TX_TYPE_SF;
 		q_idx = wmm_idx * MT76_CONNAC_MAX_WMM_SETS +
 			mt76_connac_lmac_mapping(skb_get_queue_mapping(skb));

 		/* counting non-offloading skbs */
 		wcid->stats.tx_bytes += skb->len;
 		wcid->stats.tx_packets++;
 	}

 	val = FIELD_PREP(MT_TXD0_TX_BYTES, skb->len + sz_txd) |
 	      FIELD_PREP(MT_TXD0_PKT_FMT, p_fmt) |
 	      FIELD_PREP(MT_TXD0_Q_IDX, q_idx);
 	txwi[0] = cpu_to_le32(val);

 	val = FIELD_PREP(MT_TXD1_WLAN_IDX, wcid->idx) |
 	      FIELD_PREP(MT_TXD1_OWN_MAC, omac_idx);

 	if (band_idx)
 		val |= FIELD_PREP(MT_TXD1_TGID, band_idx);

 	txwi[1] = cpu_to_le32(val);
 	txwi[2] = 0;

 	val = FIELD_PREP(MT_TXD3_REM_TX_COUNT, 15);

 	if (key)
 		val |= MT_TXD3_PROTECT_FRAME;
 	if (info->flags & IEEE80211_TX_CTL_NO_ACK)
 		val |= MT_TXD3_NO_ACK;
 	if (wcid->amsdu)
 		val |= MT_TXD3_HW_AMSDU;

 	txwi[3] = cpu_to_le32(val);
 	txwi[4] = 0;

 	val = FIELD_PREP(MT_TXD5_PID, pid);
 	if (pid >= MT_PACKET_ID_FIRST) {
 		val |= MT_TXD5_TX_STATUS_HOST;
 		txwi[3] |= cpu_to_le32(MT_TXD3_BA_DISABLE);
 		txwi[3] &= ~cpu_to_le32(MT_TXD3_HW_AMSDU);
 	}

 	txwi[5] = cpu_to_le32(val);

 	val = MT_TXD6_DAS | FIELD_PREP(MT_TXD6_MSDU_CNT, 1);
-	if (!ieee80211_vif_is_mld(vif) ||
-	    (q_idx >= MT_LMAC_ALTX0 && q_idx <= MT_LMAC_BCN0))
+	if (vif && (!ieee80211_vif_is_mld(vif) ||
+	    (q_idx >= MT_LMAC_ALTX0 && q_idx <= MT_LMAC_BCN0)))
 		val |= MT_TXD6_DIS_MAT;
 	txwi[6] = cpu_to_le32(val);
 	txwi[7] = 0;

 	if (is_8023)
 		mt7925_mac_write_txwi_8023(txwi, skb, wcid);
 	else
 		mt7925_mac_write_txwi_80211(dev, txwi, skb, key);

 	if (txwi[1] & cpu_to_le32(MT_TXD1_FIXED_RATE)) {
 		struct ieee80211_hdr *hdr = (struct ieee80211_hdr *)skb->data;
 		bool mcast = ieee80211_is_data(hdr->frame_control) &&
 			     is_multicast_ether_addr(hdr->addr1);
 		u8 idx = MT792x_BASIC_RATES_TBL;

 		if (mvif) {
 			if (mcast && mvif->mcast_rates_idx)
 				idx = mvif->mcast_rates_idx;
 			else if (beacon && mvif->beacon_rates_idx)
 				idx = mvif->beacon_rates_idx;
 			else
 				idx = mvif->basic_rates_idx;
 		}

 		txwi[6] |= cpu_to_le32(FIELD_PREP(MT_TXD6_TX_RATE, idx));
 		txwi[3] |= cpu_to_le32(MT_TXD3_BA_DISABLE);
 	}
 }
 EXPORT_SYMBOL_GPL(mt7925_mac_write_txwi);


